pub fn ticket_in_source(source: &str, ticket: &str) -> bool {
    source.contains(ticket)
}

fn extract_filter_crossing(src: &str) -> String {
    let start = match src.find("async filterCrossing") {
        Some(v) => v,
        None => return String::new(),
    };
    src[start..].to_string()
}

pub fn env007_live_path_landed(filter_source: &str) -> bool {
    let body = extract_filter_crossing(filter_source);
    if body.is_empty() {
        return ticket_in_source(filter_source, "AEP28-ENV-007");
    }
    if body.contains("admitCollectAll") == false {
        return false;
    }
    if body.contains("if (labLatticeFilterEnabled()) { return") {
        return false;
    }
    if body.contains("if (labLatticeFilterEnabled()) return") {
        return false;
    }
    true
}

