fn is_scan_name(name: &str) -> bool {
    name.ends_with(".rs")
        || name.ends_with(".gaplune")
        || name.ends_with(".ts")
        || name.ends_with(".mjs")
        || name.ends_with(".md")
        || name.ends_with(".sh")
}

fn skip_dir_name(name: &str) -> bool {
    name == ".git" || name == "target" || name == "node_modules"
}

fn collect_sources(root: &Path, out: &mut Vec<(String, String)>) {
    let mut stack = Vec::new();
    stack.push(root.to_path_buf());
    while let Some(dir) = stack.pop() {
        let rd = match fs::read_dir(&dir) {
            Ok(v) => v,
            Err(_) => continue,
        };
        for ent in rd.flatten() {
            let path = ent.path();
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("")
                .to_string();
            if skip_dir_name(&name) {
                continue;
            }
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            if is_scan_name(&name) == false {
                continue;
            }
            if let Ok(src) = fs::read_to_string(&path) {
                out.push((path.to_string_lossy().into_owned(), src));
            }
        }
    }
}

pub fn evidence_for_ticket(files: &[(String, String)], ticket: &str) -> Option<String> {
    for (path, src) in files {
        if path.contains("envelope-journals") {
            continue;
        }
        if ticket_in_source(src, ticket) {
            return Some(path.clone());
        }
    }
    None
}

pub fn scan_wave(root: &Path) -> WaveReport {
    let mut files = Vec::new();
    collect_sources(root, &mut files);
    let filter_src = files
        .iter()
        .find(|(p, _)| p.ends_with("HyperlatticeFilter.ts"))
        .map(|(_, s)| s.as_str())
        .unwrap_or("");
    let mut landed = Vec::new();
    let mut missing = Vec::new();
    for ticket in PRODUCT_TICKETS {
        if let Some(ev) = evidence_for_ticket(&files, ticket) {
            landed.push(TicketLanded {
                ticket: (*ticket).to_string(),
                landed: true,
                evidence: ev,
            });
            continue;
        }
        if *ticket == "AEP28-ENV-007" && env007_live_path_landed(filter_src) {
            landed.push(TicketLanded {
                ticket: (*ticket).to_string(),
                landed: true,
                evidence: String::from("live filterCrossing always Admit collect-all"),
            });
            continue;
        }
        missing.push((*ticket).to_string());
        landed.push(TicketLanded {
            ticket: (*ticket).to_string(),
            landed: false,
            evidence: String::new(),
        });
    }
    WaveReport { landed, missing }
}

pub fn journal_allow(wave: &WaveReport) -> JournalVerdict {
    if wave.missing.is_empty() {
        JournalVerdict {
            allow: true,
            reason: String::from("product wave landed; journals allowed on Admit crate"),
            wave: wave.clone(),
        }
    } else {
        let mut reason = String::from("journals denied until product tickets land: ");
        reason.push_str(&wave.missing.join(","));
        JournalVerdict {
            allow: false,
            reason,
            wave: wave.clone(),
        }
    }
}

pub fn run_gate(root: &Path) -> JournalVerdict {
    let wave = scan_wave(root);
    journal_allow(&wave)
}

pub fn format_verdict(v: &JournalVerdict) -> String {
    let mut out = String::new();
    if v.allow {
        out.push_str("allow\n");
    } else {
        out.push_str("deny\n");
    }
    out.push_str(&v.reason);
    out.push('\n');
    for t in &v.wave.landed {
        out.push_str(&t.ticket);
        if t.landed {
            out.push_str(" landed ");
            out.push_str(&t.evidence);
        } else {
            out.push_str(" missing");
        }
        out.push('\n');
    }
    out
}

fn err_msg(msg: String) -> anyhow::Error {
    anyhow::Error::msg(msg)
}

