#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::PathBuf;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn must(cond: bool) {
        if cond == false {
            std::process::abort();
        }
    }

    fn temp_root(tag: &str) -> PathBuf {
        let n = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(1);
        let mut name = String::from("aep-env-011-");
        name.push_str(tag);
        name.push('-');
        name.push_str(&n.to_string());
        let p = PathBuf::from("/tmp").join(name);
        let _ = fs::create_dir_all(&p);
        p
    }

    fn write_file(root: &Path, rel: &str, body: &str) {
        let p = root.join(rel);
        if let Some(parent) = p.parent() {
            let _ = fs::create_dir_all(parent);
        }
        fs::write(&p, body.as_bytes()).expect("write fixture");
    }

    fn good_filter() -> &'static str {
        "export class HyperlatticeFilter {\n  async filterCrossing(event) {\n    const admit = admitCollectAll(walls);\n    const applied = admit.allow;\n    if (labLatticeFilterEnabled()) {\n      await this.latticeFilter.filterAsync(event);\n    }\n    return { admit, applied };\n  }\n}\n"
    }

    fn skip_filter() -> &'static str {
        "export class HyperlatticeFilter {\n  async filterCrossing(event) {\n    if (labLatticeFilterEnabled()) { return this.latticeFilter.filterAsync(event); }\n    return runEvaluationChain(event);\n  }\n}\n"
    }

    fn plant_wave(root: &Path, with007_ticket: bool) {
        write_file(root, "envelope-walls/crate/src/lib.rs", "// AEP28-ENV-001\n");
        write_file(
            root,
            "admit-writing-walls/aep-registration.gaplune",
            "ticket: AEP28-ENV-002\n",
        );
        write_file(
            root,
            "admit-trust-floor/aep-registration.gaplune",
            "ticket: AEP28-ENV-003\n",
        );
        write_file(
            root,
            "admit-channel-order-walls/aep-registration.gaplune",
            "ticket: AEP28-ENV-004\n",
        );
        write_file(
            root,
            "admit-temporal-bounds/aep-registration.gaplune",
            "ticket: AEP28-ENV-005\n",
        );
        write_file(
            root,
            "live-crossing-admit-apply/crate/src/lib.rs",
            "// AEP28-ENV-006\n",
        );
        if with007_ticket {
            let mut body = String::from("// AEP28-ENV-007\n");
            body.push_str(good_filter());
            write_file(
                root,
                "dynAEP/bridge/hyperlattice/HyperlatticeFilter.ts",
                &body,
            );
        } else {
            write_file(
                root,
                "dynAEP/bridge/hyperlattice/HyperlatticeFilter.ts",
                good_filter(),
            );
        }
        write_file(
            root,
            "envelope-algebra/aep-registration.gaplune",
            "ticket: AEP28-ENV-008\n",
        );
        write_file(
            root,
            "envelope-product-copy/aep-registration.gaplune",
            "ticket: AEP28-ENV-009\n",
        );
        write_file(
            root,
            "envelope-algebra-ci/aep-registration.gaplune",
            "ticket: AEP28-ENV-010\n",
        );
    }

    #[test]
    fn ticket_in_source_detects_registration() {
        must(ticket_in_source("ticket: AEP28-ENV-010\n", "AEP28-ENV-010") == true);
        must(ticket_in_source("ticket: AEP28-ENV-009\n", "AEP28-ENV-010") == false);
    }

    #[test]
    fn env007_good_filter_lands() {
        must(env007_live_path_landed(good_filter()) == true);
    }

    #[test]
    fn env007_skip_filter_does_not_land() {
        must(env007_live_path_landed(skip_filter()) == false);
    }

    #[test]
    fn missing_tickets_deny_journals() {
        let root = temp_root("missing");
        write_file(&root, "only.md", "nothing\n");
        let v = run_gate(&root);
        must(v.allow == false);
        must(v.wave.missing.is_empty() == false);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn full_wave_allows_journals() {
        let root = temp_root("full");
        plant_wave(&root, true);
        let v = run_gate(&root);
        must(v.allow == true);
        must(v.wave.missing.is_empty() == true);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn env007_via_live_filter_without_ticket_line() {
        let root = temp_root("env007-filter");
        plant_wave(&root, false);
        let v = run_gate(&root);
        must(v.allow == true);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn journal_before_wave_denied() {
        let root = temp_root("before");
        write_file(&root, "envelope-walls/crate/src/lib.rs", "// AEP28-ENV-001\n");
        let v = run_gate(&root);
        must(v.allow == false);
        must(v.reason.contains("journals denied") == true);
        let mut gate = journal_gate::JournalGate::new();
        gate.wave = root.to_string_lossy().into_owned();
        must(gate.process().is_err() == true);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn modules_process_on_planted_wave() {
        let root = temp_root("mods");
        plant_wave(&root, true);
        let mut one = product_ticket_landed::ProductTicketLanded::new();
        one.ticket = String::from("AEP28-ENV-008");
        one.source = String::from("ticket: AEP28-ENV-008\n");
        must(one.process().is_ok() == true);
        must(one.landed.as_str() == "true");
        let mut wave = product_wave_landed::ProductWaveLanded::new();
        wave.tree = root.to_string_lossy().into_owned();
        must(wave.process().is_ok() == true);
        let mut gate = journal_gate::JournalGate::new();
        gate.wave = root.to_string_lossy().into_owned();
        must(gate.process().is_ok() == true);
        must(gate.allow.as_str() == "true");
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn live_components_tree_when_present() {
        let root = default_components_root();
        if root.is_dir() == false {
            return;
        }
        let v = run_gate(&root);
        if v.allow == false {
            let formatted = format_verdict(&v);
            must(formatted.contains("deny") == true);
            return;
        }
        must(v.allow == true);
        must(default_admit_crate().is_dir() == true);
    }
}
